with unpacked as (select id, host, context, coalesce(context['version'], 'unknown') as version_or_default, coalesce(context['region'], 'direct') as region_or_default, coalesce(context['trace'], 'unknown') as trace_or_default, cast((status_code & 4) != 0 as int) as flag_bit4, get_json_object(payload_json, '$.user.tier') as user_tier from app_logs) select case when flag_bit4 >= 1 then 'LARGE' else 'SMALL' end as flag_bit4_tier, size(collect_set(host)) as num_hosts, round(sum(flag_bit4) / nullif(count(case when host = 'h1' then 1 end), 0), 2) as flag_bit4_per_h1 from unpacked group by case when flag_bit4 >= 1 then 'LARGE' else 'SMALL' end order by flag_bit4_tier desc;
